using System;using System.IO;using System.Linq;using NativeVideo;
public static class SharedAssetsChecks {
 static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static void Fails(Action action,string message){bool failed=false;try{action();}catch(IOException){failed=true;}Check(failed,message);}
 static void Write(string file,string text){Directory.CreateDirectory(Path.GetDirectoryName(file));File.WriteAllText(file,text);}
 public static int Main(string[] args){try{return Run(args);}catch(Exception e){Console.Error.WriteLine(e.GetType().FullName+": "+e.Message);return 1;}}
 static int Run(string[] args){string root=Path.GetFullPath(args[0]),project=Path.Combine(root,"games/工程 一"),second=Path.Combine(root,"games/工程 二"),library=Path.Combine(root,"共享 模型"),registry=Path.Combine(root,"state/shared.json"),work=Path.Combine(root,"work");Directory.CreateDirectory(project);Directory.CreateDirectory(second);Directory.CreateDirectory(work);
  Write(Path.Combine(library,"人物/模型 空格.model3.json"),"{\"FileReferences\":{\"Moc\":\"model.moc3\",\"Textures\":[\"../公共/贴图.png\"],\"Physics\":\"physics.json\",\"Motions\":{\"Idle\":[{\"File\":\"motions/idle.motion3.json\"}]}}}");Write(Path.Combine(library,"人物/model.moc3"),"moc fixture");Write(Path.Combine(library,"公共/贴图.png"),"texture version one");Write(Path.Combine(library,"人物/physics.json"),"{}");Write(Path.Combine(library,"人物/motions/idle.motion3.json"),"{}");Write(Path.Combine(library,"branch.png"),"branch");
  var store=new SharedAssets(registry,Path.Combine(root,"games"));var item=store.Add(library,"figure","");string id=J.S(item,"id"),reference="__shared/"+id+"/人物/模型 空格.model3.json";Check(J.S(store.Add(library,"figure","again"),"id")==id,"registration must be idempotent");Check(TerreUserData.SamePath(store.Resolve("figure",reference),Path.Combine(library,"人物/模型 空格.model3.json")),"Chinese/spaces resolve");Check(J.A(J.Get(store.List(id,"人物"),"entries")).Count==4,"directory listing");Fails(()=>store.Resolve("figure","__shared/"+id+"/../escape.png"),"traversal rejected");Fails(()=>store.Add(project,"figure",""),"project root registration rejected");
  var adapter=EngineAdapter.Select(J.O("project",project,"engineRoot",args[1],"settings",J.O("engine","webgal")));string snapshot=Path.Combine(root,"snapshot");var assets=new ProjectAssets(project,snapshot,adapter.Source,"",null,adapter){Shared=store};assets.CollectShared("figure",reference);var manifest=assets.CopyShared();Check(J.A(J.Get(manifest,"files")).Count==5,"complete model dependency closure");Check(File.Exists(Path.Combine(snapshot,"game/figure/__shared",id,"公共/贴图.png")),"parent-relative dependency preserved");string firstDigest=J.S(manifest,"digest");
  string request=Guid.NewGuid().ToString();var copied=store.Copy(request,project,"figure",reference,"模型",work,adapter);var repeat=store.Copy(request,project,"figure",reference,"模型",work,adapter);Check(J.S(copied,"reference")==J.S(repeat,"reference"),"duplicate click idempotent");var another=store.Copy(Guid.NewGuid().ToString(),project,"figure",reference,"模型",work,adapter);Check(J.S(another,"reference")!=J.S(copied,"reference"),"collision gets independent directory");Check(File.ReadAllText(Path.Combine(project,"game/figure/模型/公共/贴图.png"))=="texture version one","copy closure contains sibling texture");
  var other=store.Copy(Guid.NewGuid().ToString(),second,"figure",reference,"模型",work,adapter);Check(File.Exists(Path.Combine(second,"game/figure",J.S(other,"reference"))),"multiple projects");Write(Path.Combine(library,"公共/贴图.png"),"texture version two");Check(File.ReadAllText(Path.Combine(project,"game/figure/模型/公共/贴图.png"))=="texture version one","local copy independent of shared updates");Check(File.ReadAllText(Path.Combine(snapshot,"game/figure/__shared",id,"公共/贴图.png"))=="texture version one","prepared snapshot remains frozen");
  var next=new ProjectAssets(project,Path.Combine(root,"next"),adapter.Source,"",null,adapter){Shared=store};next.CollectShared("figure",reference);Check(J.S(next.CopyShared(),"digest")!=firstDigest,"new snapshot fingerprint detects source update");
  var full=new ProjectAssets(project,Path.Combine(root,"full-game"),adapter.Source,"",null,adapter){Shared=store};full.CollectSharedScene(J.O("sentenceList",new[]{J.O("commandRaw","changeFigure","content",reference)}));full.CollectSharedScene(J.O("sentenceList",new[]{J.O("commandRaw","changeFigure","content","__shared/"+id+"/branch.png")}));Check(J.A(J.Get(full.CopyShared(),"files")).Count==6,"full-game collection includes independent branch scenes");
  object background=store.Add(library,"background","背景"),music=store.Add(library,"bgm","音乐");string bgRef="__shared/"+J.S(background,"id")+"/branch.png",musicRef="__shared/"+J.S(music,"id")+"/branch.png";
  var settings=new ProjectAssets(project,Path.Combine(root,"settings-only"),adapter.Source,"",null,adapter){Shared=store};settings.CollectSharedConfig("; Title_img:ignored;\nTitle_img:"+bgRef+";\nTitle_bgm:"+musicRef+";\nGame_Logo:"+bgRef+"|local.png;");Check(J.A(J.Get(settings.CopyShared(),"files")).Count==2,"title/background music/logo dependencies materialized");
  var gallery=new ProjectAssets(project,Path.Combine(root,"gallery"),adapter.Source,"",null,adapter){Shared=store};gallery.CollectSharedScene(J.O("sentenceList",new[]{J.O("commandRaw","unlockCg","content",bgRef),J.O("commandRaw","unlockBgm","content",musicRef),J.O("commandRaw","setVar","content","model='"+reference+"'")}));Check(J.A(J.Get(gallery.CopyShared(),"files")).Count==7,"gallery and literal asset variables materialized");
  var changing=new ProjectAssets(project,Path.Combine(root,"changing"),adapter.Source,"",null,adapter){Shared=store};changing.CollectShared("figure",reference);Write(Path.Combine(library,"人物/physics.json"),"{\"changed\":true}");Fails(()=>changing.CopyShared(),"source update during preparation rejected");Check(J.S(store.Relocate(id,library),"id")==id,"relocation retains stable alias");
  store.SaveResourcePort(39211);string imageReference="__shared/"+id+"/branch.png",httpSource="changeBg:"+store.ResourceUrl("figure",imageReference)+";";var httpCopy=new ProjectAssets(project,Path.Combine(root,"http-cross-category"),adapter.Source,"",null,adapter){Shared=store.ForHttpSource(httpSource)};httpCopy.CollectSharedSource(httpSource);httpCopy.CopyShared();Check(File.Exists(Path.Combine(httpCopy.Root,"game/background",imageReference)),"HTTP image used as background materializes from legacy figure registration");Check(store.KindForId(id)=="figure","HTTP preparation does not mutate original registration kind");
  string configSource="Title_img:"+store.ResourceUrl("figure",imageReference)+";\nTitle_bgm:"+store.ResourceUrl("bgm",musicRef)+";\nGame_Logo:"+store.ResourceUrl("figure",imageReference)+"|https://example.invalid/logo.png;";Write(Path.Combine(project,"game/config.txt"),configSource);
  var configOnly=new ProjectAssets(project,Path.Combine(root,"http-config-only"),adapter.Source,"",null,adapter){Shared=store};configOnly.Skeleton();configOnly.Shared=configOnly.Shared.ForHttpSource("");configOnly.CollectSharedConfig(configSource);var configManifest=configOnly.CopyShared();string preparedConfig=File.ReadAllText(Path.Combine(configOnly.Root,"game/config.txt"));Check(!preparedConfig.Contains(store.HttpPrefix)&&preparedConfig.Contains(imageReference),"HTTP config is localized in prepared project");Check(J.A(J.Get(configManifest,"files")).Count==2&&File.Exists(Path.Combine(configOnly.Root,"game/background",imageReference)),"config-only shared dependencies are copied across old category registration");Check(File.ReadAllText(Path.Combine(project,"game/config.txt"))==configSource,"config localization leaves source unchanged");Check(preparedConfig.Contains("https://example.invalid/logo.png"),"unrelated external config URL remains unchanged");
  var frozen=SharedAssets.FromSnapshot(store.Export());store.Remove(id);Check(File.Exists(frozen.Resolve("figure",reference)),"queued registry snapshot survives deregistration");Fails(()=>store.Resolve("figure",reference),"missing registry reports failure");Directory.Move(library,library+" moved");Fails(()=>frozen.Resolve("figure",reference),"missing shared source reports failure");Check(File.Exists(Path.Combine(snapshot,"game/figure/__shared",id,"人物/模型 空格.model3.json")),"existing snapshot survives source removal");var portable=new ProjectAssets(snapshot,Path.Combine(root,"portable-rerender"),adapter.Source,"",null,adapter){Shared=SharedAssets.FromSnapshot(J.O())};Check(File.Exists(portable.Resolve("figure",reference)),"materialized project resolves without registration");var literal=new ProjectAssets(snapshot,Path.Combine(root,"portable-literal"),adapter.Source,"",null,adapter){Shared=SharedAssets.FromSnapshot(J.O())};literal.CollectSharedScene(J.O("sentenceList",new[]{J.O("commandRaw","setVar","content","model='"+reference+"'")}));literal.CopyShared();Check(File.Exists(Path.Combine(literal.Root,"game/figure",reference)),"materialized literal resolves without registration");Check(Directory.GetFiles(Path.Combine(literal.Root,"game/figure/__shared",id),"*",SearchOption.AllDirectories).Length==5,"materialized literal retains full model closure");Check(Files.Hash(Path.Combine(literal.Root,"game/figure/__shared",id,"公共/贴图.png"))==Files.Hash(Path.Combine(snapshot,"game/figure/__shared",id,"公共/贴图.png")),"materialized literal retains dependency bytes");
  var absent=new ProjectAssets(snapshot,Path.Combine(root,"portable-absent"),adapter.Source,"",null,adapter){Shared=SharedAssets.FromSnapshot(J.O())};absent.CollectSharedScene(J.O("sentenceList",new[]{J.O("commandRaw","setVar","content","model='__shared/absent/missing.model3.json'")}));Fails(()=>absent.CopyShared(),"missing literal source and local copy still fail");
  Check(!Directory.EnumerateDirectories(work).Any(),"copy staging cleaned");Console.WriteLine("PASS "+checks+" shared asset production checks");return 0;
 }
}
